29	/// Primär UNDEFINIERT — jede UNTERSTÜTZTE Gattung liefert eine vollständige Spezialisierung. Eine Gattung ohne
30	/// Spezialisierung ist (noch) nicht baubar — der Baum trägt ihre Achsen, aber es gibt keine Komposition/Anatomie.
31	template <cea::AnatomyGenus G>
32	struct GenusBindingTraits;
33	
34	/// SearchAlgorithm — der VERIFIZIERTE Spezialfall (alle 4 Brücken literal grün). 19-Slot-Komposition
35	/// (17 Such-Achsen + queuing q1/q2 als reguläre SA-Achse, Doc 30 §8.0).
36	template <>
37	struct GenusBindingTraits<cea::AnatomyGenus::SearchAlgorithm> {
38	    static constexpr cea::AnatomyGenus genus      = cea::AnatomyGenus::SearchAlgorithm;
39	    static constexpr std::size_t       slot_count = 19;
40	    static constexpr std::string_view  name       = "SearchAlgorithm";
41	
42	    /// Blatt-PermTuple<19> → reale Komposition (AdHocComposition<19>) → Gattungs-Anatomie.
43	    template <class PermT>
44	    using CompositionFor = cea::CompositionFromPermTuple<PermT>;
45	    template <class Comp>
46	    using AnatomyFor = cea::SearchAlgorithmAnatomy<Comp>;
47	
48	    /// Die Achsen-Namen der Komposition-Slots (Reihenfolge T0..T18) — zentrale Pfad-Konvention (BR-2).
49	    [[nodiscard]] static constexpr std::array<std::string_view, 19> const& axis_names() noexcept {
50	        return kCompositionAxisNames;
51	    }
52	};
