54	/// Adapter — Tier-Unterklasse der CONTAINER-Gattung (std::stack/queue/priority_queue), #87+#90 / Doku 14 §28.
55	/// 13 Achsen = 12 geteilt/delegiert (§28 Invertebrate) + inner_container (NEU axis_inner, spezifisch). KEINE
56	/// „ordering"-Achse (§28 kennt keine; frühere inner+ordering-Version war geraten + verworfen). Gebaut analog
57	/// SequenceComposition. name = Tier-Unterklasse "Adapter" (konsistent mit Set/Sequence/View); Gattung = Container
58	/// (cea::gattung_of(Adapter)). Cross-Genus type-unmöglich → getrennte Komposition/Anatomie/Observer.
59	template <>
60	struct GenusBindingTraits<cea::AnatomyGenus::Adapter> {
61	    static constexpr cea::AnatomyGenus   genus      = cea::AnatomyGenus::Adapter;     // Tier-Unterklasse (Ebene 2)
62	    static constexpr cea::AnatomyGattung gattung    = cea::AnatomyGattung::Container; // Außen-Interface (Ebene 1)
63	    static constexpr std::size_t         slot_count = 13; // 12 geteilt/delegiert + inner_container
64	    static constexpr std::string_view    name       = "Adapter";
65	
66	    /// 12 geteilte/delegierte (§28) + inner_container (Inner defaultet auf DequeInner → stack/queue-Default, §26.4).
67	    template <class T0, class T1, class T2, class T3, class T4, class T5, class T6, class T7, class T8, class T9,
68	              class T10, class T11, class Inner = cea::DequeInner<>>
69	    using CompositionFor = cea::AdapterComposition<T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, Inner>;
70	    template <class Comp>
71	    using AnatomyFor = cea::AdapterAnatomy<Comp>;
72	
73	    [[nodiscard]] static constexpr std::array<std::string_view, 13> const& axis_names() noexcept {
74	        static constexpr std::array<std::string_view, 13> kNames = {
75	            "search_algo", "cache_traversal",  "memory_layout",  "allocator",    "prefetch",
76	            "concurrency", "serialization",    "telemetry",      "value_handle", "isa",
77	            "io_dispatch", "migration_policy", "inner_container"};
78	        return kNames;
79	    }
80	};
81	
82	/// Set (Vogel, K-only) — die 3. Gattungs-Instanz (D9/L-76a). 15 Achsen-Slots (§28 Bird, kein mapping/value_handle,
83	/// K-A aufgelöst). EIGENE Komposition/Anatomie (SetAnatomy treibt Composition::search_algo als Menge K=V) +
84	/// eigener Set-Observer (Cross-Genus type-unmöglich → getrennt). Belegt: der EINE Baum bindet auch die Set-Gattung.
85	template <>
86	struct GenusBindingTraits<cea::AnatomyGenus::Set> {
87	    static constexpr cea::AnatomyGenus genus      = cea::AnatomyGenus::Set;
88	    static constexpr std::size_t       slot_count = 15;
89	    static constexpr std::string_view  name       = "Set";
90	
91	    /// 15-Slot-Komposition (Reihenfolge = §28 Bird-Spalte). Blatt-PermTuple<15> → SetComposition → SetAnatomy.
92	    template <class T0, class T1, class T2, class T3, class T4, class T5, class T6, class T7, class T8, class T9,
93	              class T10, class T11, class T12, class T13, class T14>
94	    using CompositionFor = cea::SetComposition<T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, T12, T13, T14>;
95	    template <class Comp>
96	    using AnatomyFor = cea::SetAnatomy<Comp>;
97	
98	    [[nodiscard]] static constexpr std::array<std::string_view, 15> const& axis_names() noexcept {
99	        static constexpr std::array<std::string_view, 15> kNames = {
100	            "search_algo", "cache_traversal",    "path_compression", "node_type",        "memory_layout",
101	            "allocator",   "prefetch",           "concurrency",      "serialization",    "telemetry",
102	            "isa",         "index_organization", "io_dispatch",      "migration_policy", "filter"};
103	        return kNames;
104	    }
105	};
106	
107	/// Sequence (Reptil, V-indexed) — die 4. Gattungs-Instanz (D10/L-76b). 11 Slots = 10 geteilte Achsen (§28 Reptile,
108	/// K-B aufgelöst) + axis_growth (eigene). EIGENE Komposition/Anatomie (SequenceAnatomy treibt V-Speicher + Growth-
109	/// Policy) + eigener Sequence-Observer (Cross-Genus getrennt). Belegt: der EINE Baum bindet auch die Sequence-Gattung.
110	template <>
111	struct GenusBindingTraits<cea::AnatomyGenus::Sequence> {
112	    static constexpr cea::AnatomyGenus genus      = cea::AnatomyGenus::Sequence;
113	    static constexpr std::size_t       slot_count = 11; // 10 geteilte + axis_growth
114	    static constexpr std::string_view  name       = "Sequence";
115	
116	    /// 10-geteilte + Growth-Slot (Growth defaultet auf DoublingGrowth → 10-arg-Aufrufe bleiben gültig).
117	    template <class T0, class T1, class T2, class T3, class T4, class T5, class T6, class T7, class T8, class T9,
118	              class Growth = cea::DoublingGrowth>
119	    using CompositionFor = cea::SequenceComposition<T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, Growth>;
120	    template <class Comp>
121	    using AnatomyFor = cea::SequenceAnatomy<Comp>;
122	
123	    [[nodiscard]] static constexpr std::array<std::string_view, 11> const& axis_names() noexcept {
124	        static constexpr std::array<std::string_view, 11> kNames = {
125	            "memory_layout", "allocator", "prefetch",    "concurrency",      "serialization", "telemetry",
126	            "value_handle",  "isa",       "io_dispatch", "migration_policy", "growth_policy"};
127	        return kNames;
128	    }
129	};
130	
131	/// View (Pflanze, non-owning) — die 5. (letzte) Gattungs-Instanz (D11/L-76c). 7 Slots = 4 geteilte Achsen
132	/// (§28 Plant, K-C aufgelöst) + axis_extent/axis_layout/axis_accessor (eigene). EIGENE Komposition/Anatomie
133	/// (ViewAnatomy referenziert externen Puffer non-owning, liest über layout/accessor) + eigener View-Observer.
134	template <>
135	struct GenusBindingTraits<cea::AnatomyGenus::View> {
136	    static constexpr cea::AnatomyGenus genus      = cea::AnatomyGenus::View;
137	    static constexpr std::size_t       slot_count = 7; // 4 geteilt + extent/layout/accessor
138	    static constexpr std::string_view  name       = "View";
139	
140	    /// 4-geteilte + extent/layout/accessor (alle drei defaulten → 4-arg-Aufrufe bleiben gültig).
141	    template <class T0, class T1, class T2, class T3, class Extent = cea::DynamicExtent,
142	              class Layout = cea::LayoutRight, class Accessor = cea::DefaultAccessor>
143	    using CompositionFor = cea::ViewComposition<T0, T1, T2, T3, Extent, Layout, Accessor>;
144	    template <class Comp>
145	    using AnatomyFor = cea::ViewAnatomy<Comp>;
146	
147	    [[nodiscard]] static constexpr std::array<std::string_view, 7> const& axis_names() noexcept {
148	        static constexpr std::array<std::string_view, 7> kNames = {
149	            "memory_layout", "telemetry", "value_handle", "isa", "extent_policy", "layout_policy", "accessor_policy"};
150	        return kNames;
151	    }
152	};
153	
154	/// GenusBound<G> — true gdw. die Gattung G eine Bau-Bindung (GenusBindingTraits-Spezialisierung) hat.
155	/// ALLE 5 Gattungen gebunden (D11): SearchAlgorithm + Adapter + Set + Sequence + View == true (5/5).
156	template <cea::AnatomyGenus G>
157	concept GenusBound = requires {
158	    { GenusBindingTraits<G>::slot_count } -> std::convertible_to<std::size_t>;
159	    GenusBindingTraits<G>::name;
160	};
