52	// ── BR-3 (Doc 27 §3): flacher, komposition-UNABHÄNGIGER Per-Achsen-Observer-Snapshot ──
53	/// Layout-identisch zur search/allocator-Projektion des konsolidierten anatomy-Observer-PODs (NUR uint64 →
54	/// standard_layout); der Mess-Treiber
55	/// (node_value_measurement.hpp) flacht `observe_all()`/`tier_observe` einer REALEN Komposition hier hinein.
56	/// KEIN komposition-typisiertes Member → experiment_tree.hpp bleibt umbrella-unabhängig (Doc 27 §3 BR-3).
57	/// R5.B-Grenze (ehrlich): real getrieben werden search_algo + allocator; `observable_axis_count` macht
58	/// transparent, wie viele der Achsen real beobachtet sind (Rest = passive Compile-Time-Deskriptoren / Default 0).
59	struct NodeObserverSnapshot {
60	    // Legacy-V1-Projektion (Übergang, entfällt I-C): 13 benannte Felder = Sicht auf axis_stats[0] (search) /
61	    // axis_stats[6] (allocator) + Meta. Bleiben für die (noch nicht migrierten) 13-Feld-Konsumenten (CSV-o.*-
62	    // Spalten, host_measure_loop, test_d14b/d14c). Auf ingest aus der vollen Matrix abgeleitet.
63	    std::uint64_t search_lookup_count = 0, search_hit_count = 0, search_miss_count = 0, search_insert_count = 0,
64	                  search_erase_count = 0, search_peak_occupancy = 0;
65	    std::uint64_t alloc_bytes_allocated = 0, alloc_bytes_in_use = 0, alloc_allocation_count = 0,
66	                  alloc_deallocation_count = 0, alloc_failure_count = 0;
67	    std::uint64_t observable_axis_count = 0; // ObserverAggregate::observable_count() — wie viele Achsen real
68	    std::uint64_t tier_fill_level       = 0; // tier_size() zum Snapshot-Zeitpunkt
69	    // KONSOLIDIERUNG (I-B.3, 2026-06-04, User-Fork „voll auf axis_stats[19][8] migrieren"): die VOLLE Per-Achsen-
70	    // Matrix + das Pfad-B-Per-Achsen-Timing. Das Wire-Format (format_perm_result↔ingest_result_line) trägt sie,
71	    // der Baum persistiert sie. FLACHE uint64/int64-Felder (experiment_tree bleibt umbrella-/anatomy-unabhängig,
72	    // layout-identisch zu anatomy::ComdareTierObserverSnapshot ohne den Typ zu importieren). 19×8 = kV3-Schema.
73	    std::uint64_t axis_stats[19][8] = {}; // T0..T18 × 8 Felder (Schema = kV3AxisSchema)
74	    std::int64_t  seg_ns[19]        = {}; // Pfad-B Per-Achsen-Timing (ns, ALGORITHMISCHE Organ-Zeit)
75	    std::uint64_t filled_axis_count = 0;  // # Achsen mit Observer-Werten
76	    std::uint64_t batches_measured  = 0;  // # Timing-Batches (Warmup verworfen)
77	    // P-MD3 (2026-06-18): kommensurabler Coverage-Nenner + benannter Rest des Pfad-B-Segment-Laufs (additiv).
78	    std::int64_t seg_framework_ns = 0; // = seg_run_total_ns − Σseg_ns (Loop-/Instrumentierungs-Overhead)
79	    std::int64_t seg_run_total_ns = 0; // äußere Wall-Clock des Segment-Mess-Laufs (Coverage-Nenner)
80	};
