115	/// StaticAxisNode — compile-time-Entscheidung → je Static-Pfad eine Tier-Binary.
116	class StaticAxisNode final : public INodeDescription {
117	public:
118	    StaticAxisNode(std::string axis, std::string value, bool pinned, std::string block_id = {})
119	        : axis_{std::move(axis)}, value_{std::move(value)}, pinned_{pinned}, block_id_{std::move(block_id)} {}
120	    NodeKind           kind() const noexcept override { return NodeKind::Static; }
121	    std::string        axis() const override { return axis_; }
122	    std::string        value() const override { return value_; }
123	    std::string        serialize() const override { return axis_ + "=" + value_; }
124	    bool               contributes_to_signature() const noexcept override { return true; }
125	    bool               contributes_to_pinned_signature() const noexcept override { return pinned_; }
126	    bool               is_runtime_loop() const noexcept override { return false; }
127	    std::string        block_id() const override { return block_id_; } // Rück-Referenz auf den compile-time AxisBlock
128	    [[nodiscard]] bool pinned() const noexcept { return pinned_; }
129	
130	private:
131	    std::string axis_, value_;
132	    bool        pinned_;
133	    std::string block_id_;
134	};
