180	struct TreeNode {
181	    std::unique_ptr<INodeDescription>      desc;  // null = Wurzel/lazy-Blatt
182	    std::string                            key;   // §2: serialisierte Signatur Wurzel→hier (= binary_id)
183	    NodeValue                              value; // §2: Observer-Statistics/Auswertung (aus der sparse value_map)
184	    std::vector<std::unique_ptr<TreeNode>> children;
