188	/// Statisches Achsen-Level. values.size()==1 → gepinnt (Fanout 1), >1 → freigegeben (Fanout N).
189	struct AxisLevel {
190	    std::string              axis;
191	    std::vector<std::string> values;
192	    bool                     is_static = true; // static/dynamic = KNOTEN-EIGENSCHAFT (gleichrangig im Baum)
193	    std::string              variable;         // ungenutzt für statische Ebenen
194	    std::string              block_id;         // Rück-Referenz auf den compile-time AxisBlock (Bidirektionalität)
