212	/// DAS Blatt = exakt EINE Experiment-Einstellung (Binary × eine vollständige dynamische Belegung).
213	struct ExperimentSetting {
214	    std::string              binary_id;             // statische Rekombination = die Tier-Binary
215	    std::string              pinned_signature;      // Paper-Wiedererkennung (KF-15)
216	    std::vector<std::string> dynamic_assignment;    // akkumulierte dyn. Belegung (je "axis.var=value")
217	    std::string              setting_id;            // binary_id + dyn. Belegung = eindeutige ID (ersetzt fingerprint)
218	    TreeNode const*          binary_node = nullptr; // bei lazy Iteration nullptr (kein persistenter Baum)
