221	// ── KF-16 / Doc 26 §2 — indizierte LAZY Sicht auf den STATISCHEN Teilbaum ──
222	/// Die statischen Eigenschaften EINER zu kompilierenden Tier-Binary (= ein Static-Pfad/Blatt).
223	struct BinarySpec {
224	    std::size_t                                      index = 0;        // 0-basiert, stabile Reihenfolge
225	    std::string                                      binary_id;        // serialisierter Static-Pfad = die Binary
226	    std::string                                      pinned_signature; // gepinnte Achsen (Paper-Wiedererkennung)
227	    std::vector<std::pair<std::string, std::string>> axes;             // (achse, wert) je statischer Ebene
228	};
