91	        map.clear();
92	
93	        // RF1 dagger-empty/find/count/contains: leeres Tier -> Lookup-Miss, Groesse 0, empty/count/contains false.
94	        auto const    rf1_total  = r.cases_total;
95	        auto const    rf1_passed = r.cases_passed;
96	        std::uint64_t v          = 123;
